script:
(function () {
	/* ── Step definitions ──────────────────────────────────────── */
	const STEPS = [
		{
			key: "department",
			label: "Department Structure",
			desc: "Define your organization's department hierarchy and reporting units.",
			icon: "🏢",
		},
		{
			key: "hierarchy",
			label: "Reporting Hierarchy",
			desc: "Map out who reports to whom across your staffing network.",
			icon: "🔗",
		},
		{
			key: "employee",
			label: "Employee Setup",
			desc: "Import or create employee records and assign them to departments.",
			icon: "👤",
		},
		{
			key: "erp_configuration",
			label: "ERP Configuration",
			desc: "Configure core ERP settings for payroll, attendance, and compliance.",
			icon: "⚙️",
		},
		{
			key: "pdf_agreement_template",
			label: "Agreement Templates",
			desc: "Upload offer letter and employment agreement PDF templates.",
			icon: "📄",
		},
	];

	/* ── Change 1 & 2: Frappe navigation helper ────────────────── */
	/*
	 * navigateToRoute(route)
	 *
	 * Handles three cases:
	 *   /app/employee/new            → frappe.new_doc("Employee")
	 *   /app/pdf-agreement-template/new → frappe.new_doc("Pdf Agreement Template")
	 *   anything else                → frappe.set_route(...)
	 *
	 * Route is split on "/" and the leading empty segment from
	 * "/app/..." is dropped before passing to set_route so Frappe
	 * receives ["app", "doctype", ...] as it expects.
	 */
	function navigateToRoute(route) {
		if (!route) return;

		/* Normalize: strip leading slash, split into segments */
		const segments = route.replace(/^\//, "").split("/");
		// segments[0] = "app", segments[1] = doctype slug, segments[2] = "new" (maybe)

		const isNewDoc = segments.length >= 3 && segments[segments.length - 1] === "new";

		if (isNewDoc) {
			/* Map URL slug to Frappe doctype name */
			const slug = segments[1];
			const DOCTYPE_MAP = {
				employee: "Employee",
				"pdf-agreement-template": "Pdf Agreement Template",
			};
			const doctype = DOCTYPE_MAP[slug] || slugToDoctype(slug);
			frappe.new_doc(doctype);
		} else {
			/* Standard Frappe route navigation — pass segments directly */
			frappe.set_route(segments);
		}
	}

	/* Fallback: convert a kebab-slug to Title Case doctype name */
	function slugToDoctype(slug) {
		return slug
			.split("-")
			.map((w) => w.charAt(0).toUpperCase() + w.slice(1))
			.join(" ");
	}

	/* ── Helpers ───────────────────────────────────────────────── */
	function show(id) {
		root_element.getElementById(id).style.display = "";
	}
	function hide(id) {
		root_element.getElementById(id).style.display = "none";
	}

	function getStepState(key, steps, currentStep) {
		if (steps[key] === true) return "done";
		if (key === currentStep) return "current";
		return "pending";
	}

	/* ── Change 3: Hero — button instead of anchor, no onclick ─── */
	function buildHero(data) {
		const pct = data.progress_percentage || 0;
		const done = data.completed_steps || 0;
		const total = data.total_steps || 5;
		const currentStep = data.next_action?.label || "Continue Setup";

		return `
		<div class="sw-hero">

		<div class="sw-hero-top">
			<div>
			<div class="sw-hero-label">
				Staffing ERP Setup
			</div>

			<h1>Setup Progress</h1>

			<p class="sw-hero-sub">
				${done} of ${total} steps completed
			</p>
			</div>

			<div class="sw-progress-pill">
			${pct}% Complete
			</div>
		</div>

		<div class="sw-progress-track">
			<div class="sw-progress-fill" id="sw-prog-fill"></div>
		</div>

		<div class="sw-current-step">
			<span>Current Step</span>
			<strong>${currentStep}</strong>
		</div>

		<div class="sw-hero-actions">
			<button
			class="sw-btn sw-btn-primary sw-continue-setup"
			type="button"
			>
			Continue Setup →
			</button>

			<button
			class="sw-btn sw-btn-secondary"
			type="button"
			onclick="swInit()"
			>
			Refresh
			</button>
		</div>

		</div>
	`;
	}

	/* ── Build Steps Journey ───────────────────────────────────── */
	function buildJourney(data) {
		const stepsHtml = STEPS.map((s) => {
			const state = getStepState(s.key, data.steps, data.current_step);
			const badge = {
				done: '<span class="sw-step-badge sw-badge-done">Done</span>',
				current: '<span class="sw-step-badge sw-badge-current">In progress</span>',
				pending: '<span class="sw-step-badge sw-badge-pending">Pending</span>',
			}[state];

			return `
        <div class="sw-step ${state}">
          <div class="sw-step-icon">${state === "done" ? "✓" : s.icon}</div>
          <div class="sw-step-body">
            <div class="sw-step-title">${s.label}</div>
            <div class="sw-step-desc">${s.desc}</div>
          </div>
          ${badge}
        </div>`;
		}).join("");

		return `
      <div class="sw-card">
        <div class="sw-card-header">
          <div>
            <div class="sw-card-title">Setup Journey</div>
            <div class="sw-card-subtitle">Complete each step to finish onboarding</div>
          </div>
        </div>
        <div class="sw-steps">${stepsHtml}</div>
      </div>`;
	}

	/* ── Change 9: Updated completion copy ────────────────────── */
	function buildCompletion() {
		return `
      <div class="sw-complete-card">
        <div class="sw-complete-icon">🎉</div>
        <h2>Setup Complete</h2>
        <p>Your organization is fully configured and ready for daily operations.</p>
        <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">
          <button class="sw-btn sw-btn-success" type="button" onclick="navigateToRoute('/app')">
            Go to Dashboard &rarr;
          </button>
          <button class="sw-btn sw-btn-ghost-white" type="button"
            style="border-color:#A7F3D0;color:#065F46;background:transparent;"
            onclick="swHideWorkspace()">
            Hide Setup Workspace
          </button>
        </div>
      </div>`;
	}

	/* ── Build Hide Row ────────────────────────────────────────── */
	function buildHideRow() {
		return `
      <div class="sw-hide-row">
        <button class="sw-btn-hide" type="button" onclick="swHideWorkspace()">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor"
               stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/>
            <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/>
            <line x1="1" y1="1" x2="23" y2="23"/>
          </svg>
          Hide Setup Workspace
        </button>
      </div>`;
	}

	/* ── Change 5: Bind event handlers after render ────────────── */
	/*
	 * Called after main.innerHTML is written.
	 * Attaches click handlers to .sw-continue-setup and .sw-next-action
	 * using the current data captured in the closure.
	 * No inline onclick attributes used on these two buttons.
	 */
	function bindRouteHandlers(data) {
		const nextRoute = data.next_action?.route || "/app";

		const continueBtn = root_element.querySelector(".sw-continue-setup");
		if (continueBtn) {
			continueBtn.addEventListener("click", function () {
				navigateToRoute(nextRoute);
			});
		}

		const nextActionBtn = root_element.querySelector(".sw-next-action");
		if (nextActionBtn) {
			nextActionBtn.addEventListener("click", function () {
				navigateToRoute(nextRoute);
			});
		}
	}

	/* ── Render full UI ────────────────────────────────────────── */
	function render(data) {
		const main = root_element.getElementById("sw-main-state");

		if (data.is_completed) {
			main.innerHTML = buildCompletion();
			return;
		}

		main.innerHTML = `
    ${buildHero(data)}
	${buildJourney(data)}
	${buildHideRow()}
    `;

		/* Change 5: bind route handlers after DOM is written */
		bindRouteHandlers(data);

		/* Change 6: progress bar starts at 0% (CSS default), animate to real value */
		requestAnimationFrame(() => {
			requestAnimationFrame(() => {
				const fill = root_element.getElementById("sw-prog-fill");
				if (fill) fill.style.width = (data.progress_percentage || 0) + "%";
			});
		});
	}

	/* ── Hide Workspace ────────────────────────────────────────── */
	window.swHideWorkspace = function () {
		frappe.call({
			method: "verp_staffing.utils.onboarding_setup_helper.hide_setup_workspace",
			callback: function (r) {
				frappe.show_alert({
					message: "Setup Workspace hidden successfully.",
					indicator: "green",
				});
				setTimeout(() => {
					if (frappe.get_route()[0] === "workspace") {
						frappe.set_route("workspace");
					} else {
						window.location.reload();
					}
				}, 1200);
			},
			error: function () {
				frappe.show_alert({
					message: "Could not hide workspace. Please try again.",
					indicator: "red",
				});
			},
		});
	};

	/* ── Init ──────────────────────────────────────────────────── */
	window.swInit = function () {
		hide("sw-main-state");
		hide("sw-error-state");
		show("sw-loading-state");

		frappe.call({
			method: "verp_staffing.utils.onboarding_setup_helper.get_setup_progress",
			callback: function (r) {
				hide("sw-loading-state");
				if (r && r.message) {
					render(r.message);
					show("sw-main-state");
				} else {
					show("sw-error-state");
				}
			},
			error: function () {
				hide("sw-loading-state");
				show("sw-error-state");
			},
		});
	};

	/* ── Bootstrap ─────────────────────────────────────────────── */
	if (typeof frappe !== "undefined") {
		frappe.ready ? frappe.ready(swInit) : swInit();
	} else {
		/* Dev preview fallback with sample data */
		setTimeout(() => {
			hide("sw-loading-state");
			render({
				completed_steps: 3,
				total_steps: 5,
				progress_percentage: 60,
				current_step: "erp_configuration",
				current_step_label: "Configure ERP Settings",
				is_completed: false,
				next_action: {
					label: "Configure ERP Settings",
					doctype: "ERP Configuration",
					route: "/app/erp-configuration",
				},
				steps: {
					department: true,
					hierarchy: true,
					employee: true,
					erp_configuration: false,
					pdf_agreement_template: false,
				},
			});
			show("sw-main-state");
		}, 800);
	}
})();

style:
/* ── Reset & Base ─────────────────────────────────────────── */
#sw-root * {
	box-sizing: border-box;
	margin: 0;
}

#sw-root {
	--c-primary: #3b82f6;
	--c-primary-dk: #1d4ed8;
	--c-success: #10b981;
	--c-warning: #f59e0b;
	--c-text: #1e293b;
	--c-muted: #64748b;
	--c-bg: #f8fafc;
	--c-white: #ffffff;
	--c-border: #e2e8f0;
	--c-primary-lt: #eff6ff;
	--c-success-lt: #ecfdf5;
	--c-warning-lt: #fffbeb;
	--radius-sm: 8px;
	--radius-md: 14px;
	--radius-lg: 20px;
	--shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.07), 0 1px 2px rgba(0, 0, 0, 0.05);
	--shadow-md: 0 4px 16px rgba(0, 0, 0, 0.08), 0 1px 4px rgba(0, 0, 0, 0.04);
	--shadow-hero: 0 8px 32px rgba(59, 130, 246, 0.18);

	font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
	font-size: 14px;
	color: var(--c-text);
	background: var(--c-bg);
	padding: 24px 20px 40px;
	min-height: 100%;
}

/* ── Layout ───────────────────────────────────────────────── */
.sw-grid {
	padding: 5px !important;
	margin: 0 auto;
	display: grid;
	gap: 20px;
}

.sw-row-2 {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 20px;
}

@media (max-width: 680px) {
	.sw-row-2 {
		grid-template-columns: 1fr;
	}
	#sw-root {
		padding: 16px 12px 32px;
	}
}

/* ── Card base ────────────────────────────────────────────── */
.sw-card {
	background: #fff;
	border: 1px solid #e2e8f0;
	border-radius: 18px;
	padding: 32px;
	box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
}
.sw-btn-secondary {
	background: #fff;
	border: 1px solid #e2e8f0;
	color: #334155;
}

.sw-btn-secondary:hover {
	background: #f8fafc;
}
/* ── Hero Card ────────────────────────────────────────────── */
.sw-hero {
	background: #f7fbff;
	border: 1px solid #dcebff;
	border-radius: 20px;
	padding: 32px;
	box-shadow: 0 4px 16px rgba(15, 23, 42, 0.05);
}

.sw-hero-top {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	gap: 20px;
	margin-bottom: 20px;
	flex-wrap: wrap;
}

.sw-hero-label {
	font-size: 12px;
	font-weight: 600;
	color: #2563eb;
	margin-bottom: 8px;
}

.sw-hero h1 {
	font-size: 28px;
	font-weight: 700;
	color: #0f172a;
	margin-bottom: 6px;
}

.sw-hero-sub {
	color: #64748b;
	font-size: 14px;
}

.sw-progress-pill {
	background: #eff6ff;
	color: #2563eb;
	border: 1px solid #bfdbfe;
	padding: 8px 14px;
	border-radius: 999px;
	font-size: 13px;
	font-weight: 600;
}

.sw-progress-track {
	width: 100%;
	height: 10px;
	background: #e2e8f0;
	border-radius: 999px;
	overflow: hidden;
	margin-bottom: 24px;
}

.sw-progress-fill {
	height: 100%;
	width: 0;
	background: #2563eb;
	border-radius: 999px;
	transition: width 0.7s ease;
}

.sw-current-step {
	margin-top: 24px !important;
	margin-bottom: 24px !important;
	display: flex;
	flex-direction: column;
	gap: 4px;
}

.sw-current-step span {
	font-size: 12px;
	color: #64748b;
}

.sw-current-step strong {
	font-size: 16px;
	font-weight: 600;
	color: #0f172a;
}

.sw-hero-inner {
	position: relative;
	z-index: 1;
}

.sw-hero h1 {
	font-size: 26px;
	font-weight: 700;
	letter-spacing: -0.4px;
	line-height: 1.25;
	margin-bottom: 6px;
}

.sw-hero-sub {
	font-size: 14px;
	color: rgba(255, 255, 255, 0.75);
	margin-bottom: 28px;
	max-width: 420px;
}

.sw-progress-row {
	display: flex;
	align-items: center;
	gap: 14px;
	margin-bottom: 24px;
}

/* Change 6: Progress bar starts at 0% — width is set via JS animation */

.sw-progress-label {
	font-size: 14px;
	font-weight: 700;
	white-space: nowrap;
	color: #fff;
}

.sw-hero-actions {
	display: flex;
	gap: 10px;
	flex-wrap: wrap;
}

/* ── Buttons ──────────────────────────────────────────────── */
/* Change 8: slightly increased font-weight and min-height for all buttons */
.sw-btn {
	display: inline-flex;
	align-items: center;
	gap: 7px;
	font-size: 13.5px;
	font-weight: 700; /* was 600 */
	border: none;
	border-radius: var(--radius-sm);
	padding: 11px 22px; /* was 10px 20px — slight height increase */
	min-height: 40px; /* added: ensures consistent taller hit area */
	cursor: pointer;
	transition: all 0.18s ease;
	text-decoration: none;
	line-height: 1;
	vertical-align: middle;
}
.sw-btn:hover {
	transform: translateY(-1px);
}
.sw-btn:active {
	transform: none;
}

.sw-btn-white {
	background: var(--c-white);
	color: var(--c-primary-dk);
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}
.sw-btn-white:hover {
	box-shadow: 0 4px 16px rgba(0, 0, 0, 0.16);
}

.sw-btn-ghost-white {
	background: rgba(255, 255, 255, 0.15);
	color: var(--c-white);
	border: 1.5px solid rgba(255, 255, 255, 0.35);
}
.sw-btn-ghost-white:hover {
	background: rgba(255, 255, 255, 0.22);
}

.sw-btn-primary {
	background: var(--c-primary);
	color: #fff;
	box-shadow: 0 2px 8px rgba(59, 130, 246, 0.35);
}
.sw-btn-primary:hover {
	background: var(--c-primary-dk);
	box-shadow: 0 4px 16px rgba(59, 130, 246, 0.45);
}

.sw-btn-success {
	background: var(--c-success);
	color: #fff;
	box-shadow: 0 2px 8px rgba(16, 185, 129, 0.35);
}

/* ── Section label ────────────────────────────────────────── */
.sw-section-label {
	font-size: 11px;
	font-weight: 700;
	letter-spacing: 0.1em;
	text-transform: uppercase;
	color: var(--c-muted);
	margin-bottom: 12px;
}

/* ── Step Journey ─────────────────────────────────────────── */
.sw-steps {
    margin-top: 20px !important;
	display: flex;
	flex-direction: column;
	gap: 0;
}

.sw-step {
	display: flex;
	gap: 15px;
	position: relative;
	padding: 18px 0;
}

.sw-step:not(:last-child)::after {
	content: "";
	position: absolute;
	left: 17px;
	top: 48px;
	width: 2px;
	height: calc(100% - 24px);
	background: #e2e8f0;
}

.sw-step:last-child {
	border-bottom: none;
	padding-bottom: 0;
}
.sw-step:first-child {
	padding-top: 0;
}

/* Change 7: current step — keep existing design, add blue-tinted elevation */
.sw-step.current {
	margin: 0 -14px;
	padding: 16px 14px;
	background: #eff6ff;
	border-left: 4px solid #2563eb;
	border-radius: 12px;
}

.sw-step-icon {
	width: 36px;
	height: 36px;
	border-radius: 50%;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-shrink: 0;
	font-size: 16px;
	transition: all 0.2s;
}

.sw-step.done .sw-step-icon {
	background: #dcfce7;
	color: #16a34a;
}

.sw-step.current .sw-step-icon {
	background: var(--c-primary);
	color: #fff;
	box-shadow: 0 0 0 4px #bfdbfe;
}
.sw-step.pending .sw-step-icon {
	background: var(--c-border);
	color: var(--c-muted);
}

.sw-step-body {
	flex: 1;
	min-width: 0;
}

.sw-step-title {
	font-size: 13.5px;
	font-weight: 600;
	color: var(--c-text);
	margin-bottom: 2px;
}
.sw-step.pending .sw-step-title {
	color: var(--c-muted);
}

.sw-step-desc {
	font-size: 12px;
	color: var(--c-muted);
	line-height: 1.45;
}

.sw-step-badge {
	flex-shrink: 0;
	font-size: 11px;
	font-weight: 600;
	padding: 3px 10px;
	border-radius: 100px;
    display: flex;
    align-items: center;
}
.sw-badge-done {
	background: var(--c-success-lt);
	color: var(--c-success);
}
.sw-badge-current {
	background: #dbeafe;
	color: var(--c-primary-dk);
}
.sw-badge-pending {
	background: var(--c-bg);
	color: var(--c-muted);
	border: 1px solid var(--c-border);
}

.sw-action-eyebrow span {
	width: 6px;
	height: 6px;
	border-radius: 50%;
	background: var(--c-primary);
	display: inline-block;
	animation: sw-pulse 1.6s ease-in-out infinite;
}

@keyframes sw-pulse {
	0%,
	100% {
		opacity: 1;
		transform: scale(1);
	}
	50% {
		opacity: 0.5;
		transform: scale(0.8);
	}
}

/* ── Completion Card ──────────────────────────────────────── */
.sw-complete-card {
	background: linear-gradient(135deg, #ecfdf5 0%, #f0fdf4 100%);
	border: 1.5px solid #a7f3d0;
	border-radius: var(--radius-lg);
	padding: 40px 32px;
	text-align: center;
	box-shadow: var(--shadow-md);
}

.sw-complete-icon {
	width: 64px;
	height: 64px;
	border-radius: 50%;
	background: var(--c-success);
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 28px;
	margin: 0 auto 20px;
	box-shadow: 0 0 0 12px rgba(16, 185, 129, 0.12);
}

/* Change 9: updated heading and description text via JS buildCompletion() */
.sw-complete-card h2 {
	font-size: 22px;
	font-weight: 700;
	color: #065f46;
	margin-bottom: 8px;
}

.sw-complete-card p {
	font-size: 14px;
	color: #059669;
	margin-bottom: 28px;
}

/* ── Hide button area ─────────────────────────────────────── */
.sw-hide-row {
	display: flex;
	justify-content: flex-end;
	padding-top: 4px;
}

.sw-btn-hide {
	background: transparent;
	color: var(--c-muted);
	border: 1px solid var(--c-border);
	font-size: 12px;
	font-weight: 500;
	padding: 7px 16px;
	border-radius: var(--radius-sm);
	cursor: pointer;
	transition: all 0.18s;
	display: inline-flex;
	align-items: center;
	gap: 6px;
}
.sw-btn-hide:hover {
	color: var(--c-text);
	border-color: #94a3b8;
	background: var(--c-bg);
}

/* ── Skeleton loader ──────────────────────────────────────── */
.sw-skeleton {
	background: linear-gradient(90deg, #e2e8f0 25%, #f1f5f9 50%, #e2e8f0 75%);
	background-size: 200% 100%;
	animation: sw-shimmer 1.4s infinite;
	border-radius: 6px;
}
@keyframes sw-shimmer {
	0% {
		background-position: 200% 0;
	}
	100% {
		background-position: -200% 0;
	}
}

.sw-skel-hero {
	height: 180px;
	border-radius: var(--radius-lg);
}
.sw-skel-card {
	height: 280px;
	border-radius: var(--radius-lg);
}
.sw-skel-card2 {
	height: 200px;
	border-radius: var(--radius-lg);
}

/* ── Error state ──────────────────────────────────────────── */
.sw-error-card {
	border: 1.5px solid #fee2e2;
	background: #fff5f5;
	border-radius: var(--radius-lg);
	padding: 32px;
	text-align: center;
	color: #991b1b;
}
.sw-error-card p {
	font-size: 13px;
	color: #b91c1c;
	margin-top: 6px;
}

/* ── Card header ──────────────────────────────────────────── */
.sw-card-header {
	display: flex;
	align-items: center;
	gap: 10px;
	margin-bottom: 20px;
}
.sw-card-header-icon {
	width: 34px;
	height: 34px;
	border-radius: var(--radius-sm);
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 16px;
	flex-shrink: 0;
}
.sw-card-title {
	font-size: 20px;
	font-weight: 700;
	color: var(--c-text);
}
.sw-card-subtitle {
	font-size: 12px;
	color: var(--c-muted);
	margin-top: 1px;
}
